import json, sys
from http.server import BaseHTTPRequestHandler, HTTPServer
from urllib.parse import parse_qs, urlparse

state = {"progress": 0.0, "tag": None}

class H(BaseHTTPRequestHandler):
    def log_message(self, *a):
        pass

    def send(self, code, body, headers=()):
        self.send_response(code)
        for k, v in headers:
            self.send_header(k, v)
        self.end_headers()
        self.wfile.write(body.encode())

    def authed(self):
        return "SID=abc" in (self.headers.get("Cookie") or "")

    def do_POST(self):
        n = int(self.headers.get("Content-Length") or 0)
        form = parse_qs(self.rfile.read(n).decode())
        if self.path == "/api/v2/auth/login":
            if form.get("password") == ["pw"]:
                return self.send(200, "Ok.", [("Set-Cookie", "SID=abc; path=/")])
            return self.send(200, "Fails.")
        if self.path == "/api/v2/torrents/add":
            if not self.authed():
                return self.send(403, "Forbidden")
            print("ADD", form, file=sys.stderr)
            state["tag"] = form.get("tags", [None])[0]
            return self.send(200, "Ok.")
        self.send(404, "")

    def do_GET(self):
        u = urlparse(self.path)
        if u.path == "/api/v2/torrents/info":
            if not self.authed():
                return self.send(403, "Forbidden")
            tag = parse_qs(u.query).get("tag", [None])[0]
            if tag != state["tag"]:
                return self.send(200, "[]")
            state["progress"] = min(1.0, state["progress"] + 0.5)
            st = "uploading" if state["progress"] >= 1 else "downloading"
            return self.send(200, json.dumps([{"name": "ubuntu.iso", "progress": state["progress"], "dlspeed": 3145728, "state": st}]))
        self.send(404, "")

HTTPServer(("127.0.0.1", 18080), H).serve_forever()

