    }
}

/// 받을 수 없는 결과를 걸러내고 시더 많은 순으로 limit개만 남긴다.
pub fn rank(mut hits: Vec<Hit>, min_seeders: u32, limit: usize) -> Vec<Hit> {
    hits.retain(|h| h.seeders() >= min_seeders && h.link().is_some());
    hits.sort_by(|a, b| b.seeders().cmp(&a.seeders()));
    hits.truncate(limit);
    hits
}

#[cfg(test)]
mod tests {
    use super::*;

    fn fixture() -> Vec<Hit> {
        serde_json::from_str(include_str!("../fixtures/search.json")).unwrap()
    }

    #[test]
    fn parses_fixture() {
        let hits = fixture();
        assert_eq!(hits.len(), 5);
        assert_eq!(hits[3].seeders, None);
        assert_eq!(hits[4].link(), None);
    }

    #[test]
    fn magnet_is_preferred() {
        let hit = Hit {
            title: "a".into(),
            size: 0,
            seeders: None,
            indexer: String::new(),
            magnet_url: Some("magnet:x".into()),
            download_url: Some("http://y".into()),
        };
        assert_eq!(hit.link(), Some("magnet:x"));
    }

    #[test]
    fn rank_filters_and_sorts() {
        let ranked = rank(fixture(), 1, 10);
        let titles: Vec<_> = ranked.iter().map(|h| h.title.as_str()).collect();
        assert_eq!(
            titles,
            ["ubuntu-24.04.1-desktop-amd64.iso", "ubuntu-24.04-live-server-amd64.iso"]
        );
    }

    #[test]
    fn rank_respects_limit() {
        assert_eq!(rank(fixture(), 0, 1).len(), 1);
    }
}

