use std::fs;
use std::path::{Path, PathBuf};

use anyhow::{Context, Result};
use serde::Deserialize;

use crate::cli::Args;

/// config.toml 의 모양. 모든 칸이 비어 있어도 된다.
#[derive(Debug, Default, Deserialize)]
pub struct FileConfig {
    pub prowlarr_url: Option<String>,
    pub prowlarr_api_key: Option<String>,
    pub qbit_url: Option<String>,
    pub qbit_user: Option<String>,
    pub qbit_pass: Option<String>,
    pub save_path: Option<String>,
}

/// CLI/환경변수 > 설정 파일 > 기본값 순으로 합친 최종 설정.
#[derive(Debug)]
pub struct Settings {
    pub prowlarr_url: String,
    pub prowlarr_api_key: Option<String>,
    pub qbit_url: String,
    pub qbit_user: String,
    pub qbit_pass: String,
    pub save_path: Option<String>,
}

impl Settings {
    pub fn load(args: &Args) -> Result<Self> {
        let file = match &args.config {
            Some(path) => read_file(path)?,
            None => match default_path() {
                Some(path) if path.exists() => read_file(&path)?,
                _ => FileConfig::default(),
            },
        };
        Ok(Self::merge(args, file))
    }

    fn merge(args: &Args, file: FileConfig) -> Self {
        Self {
            prowlarr_url: args
                .prowlarr_url
                .clone()
                .or(file.prowlarr_url)
                .unwrap_or_else(|| "http://localhost:9696".into()),
            prowlarr_api_key: args.prowlarr_api_key.clone().or(file.prowlarr_api_key),
            qbit_url: args
                .qbit_url
                .clone()
                .or(file.qbit_url)
                .unwrap_or_else(|| "http://localhost:8080".into()),
            qbit_user: args
                .qbit_user
                .clone()
                .or(file.qbit_user)
                .unwrap_or_else(|| "admin".into()),
            qbit_pass: args.qbit_pass.clone().or(file.qbit_pass).unwrap_or_default(),
            save_path: args.save_path.clone().or(file.save_path),
        }
    }
}

fn default_path() -> Option<PathBuf> {
    let base = std::env::var_os("XDG_CONFIG_HOME")
        .map(PathBuf::from)
        .or_else(|| dirs::home_dir().map(|h| h.join(".config")))?;
    Some(base.join("tget").join("config.toml"))
}

fn read_file(path: &Path) -> Result<FileConfig> {
    let raw = fs::read_to_string(path)
        .with_context(|| format!("설정 파일 {} 을 읽지 못했어요", path.display()))?;
    toml::from_str(&raw).with_context(|| format!("설정 파일 {} 형식이 잘못됐어요", path.display()))
}

#[cfg(test)]
mod tests {
    use super::*;
    use clap::Parser;

    #[test]
    fn cli_wins_over_file() {
        let args = Args::parse_from(["tget", "x", "--qbit-url", "http://cli:1"]);
        let file = FileConfig {
            qbit_url: Some("http://file:2".into()),
            qbit_user: Some("me".into()),
            ..Default::default()
        };
        let s = Settings::merge(&args, file);
        assert_eq!(s.qbit_url, "http://cli:1");
        assert_eq!(s.qbit_user, "me");
        assert_eq!(s.prowlarr_url, "http://localhost:9696");
    }
}

