                return Ok(());
            }
        }
    };

    let qbit = Qbit::login(http, &settings.qbit_url, &settings.qbit_user, &settings.qbit_pass).await?;
    let tag = new_tag();
    qbit.add(chosen.link().unwrap(), settings.save_path.as_deref(), &tag)
        .await?;
    println!("→ qBittorrent에 추가됨: {}", chosen.title);

