use std::borrow::Cow;

use serde::{Deserialize, Deserializer};

/// Prowlarr 검색 결과 한 건. 문자열은 가능하면 원본 JSON에서 빌려 온다.
#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Hit<'a> {
    #[serde(borrow)]
    pub title: Cow<'a, str>,
    #[serde(default)]
    pub size: u64,
    pub seeders: Option<u32>,
    #[serde(borrow, default)]
    pub indexer: Cow<'a, str>,
    #[serde(borrow, default, deserialize_with = "opt_cow")]
    pub magnet_url: Option<Cow<'a, str>>,
    #[serde(borrow, default, deserialize_with = "opt_cow")]
    pub download_url: Option<Cow<'a, str>>,
}

/// `Option<Cow<str>>` 는 `#[serde(borrow)]` 만으로는 빌리지 않는다.
/// 빌리는 Cow를 감싼 새 타입을 거쳐서 해석하면 빌린다.
#[derive(Deserialize)]
struct BorrowedStr<'a>(#[serde(borrow)] Cow<'a, str>);

fn opt_cow<'de: 'a, 'a, D>(d: D) -> Result<Option<Cow<'a, str>>, D::Error>
where
    D: Deserializer<'de>,
{
    Ok(Option::<BorrowedStr<'a>>::deserialize(d)?.map(|b| b.0))
}

impl Hit<'_> {
    pub fn seeders(&self) -> u32 {
        self.seeders.unwrap_or(0)
    }

    pub fn link(&self) -> Option<&str> {
        self.magnet_url
            .as_deref()
            .or(self.download_url.as_deref())
            .filter(|s| !s.is_empty())
    }
}

/// 원본 JSON 문자열을 빌려서 해석한다. 결과는 raw보다 오래 살 수 없다.
pub fn parse(raw: &str) -> serde_json::Result<Vec<Hit<'_>>> {
    serde_json::from_str(raw)
}

/// 받을 수 없는 결과를 걸러내고 시더 많은 순으로 limit개만 남긴다.
pub fn rank(mut hits: Vec<Hit<'_>>, min_seeders: u32, limit: usize) -> Vec<Hit<'_>> {
