    hits.truncate(limit);
    hits
}

/// 제목에 검색어의 모든 단어가 들어 있는 결과 중 시더가 가장 많은 것.
pub fn best<'h, 'a>(hits: &'h [Hit<'a>], query: &str) -> Option<&'h Hit<'a>> {
    let words: Vec<String> = query.split_whitespace().map(str::to_lowercase).collect();
    hits.iter()
        .filter(|h| {
            let title = h.title.to_lowercase();
            words.iter().all(|w| title.contains(w.as_str()))
        })
        .max_by_key(|h| h.seeders())
}

#[cfg(test)]
mod tests {
    use super::*;

    fn fixture() -> Vec<Hit<'static>> {
        parse(include_str!("../fixtures/search.json")).unwrap()
    }

    #[test]
    fn parses_fixture() {
