        };
        assert_eq!(hit.link(), Some("magnet:x"));
    }

    #[test]
    fn rank_filters_and_sorts() {
        let ranked = rank(fixture(), 1, 10);
        let titles: Vec<_> = ranked.iter().map(|h| h.title.as_ref()).collect();
        assert_eq!(
            titles,
            [
                "ubuntu-24.04.1-desktop-amd64.iso",
                "ubuntu-24.04-live-server-amd64.iso"
            ]
        );
    }

    #[test]
    fn rank_respects_limit() {
        assert_eq!(rank(fixture(), 0, 1).len(), 1);
    }

    #[test]
    fn borrows_unless_escaped() {
        let raw = r#"[{"title":"plain","magnetUrl":"magnet:x"},{"title":"say \"hi\""}]"#;
        let hits = parse(raw).unwrap();
        assert!(matches!(hits[0].title, Cow::Borrowed(_)));
        assert!(matches!(hits[0].magnet_url, Some(Cow::Borrowed(_))));
        assert!(matches!(hits[1].title, Cow::Owned(_)));
        assert_eq!(hits[1].title, "say \"hi\"");
    }

    #[test]
    fn best_matches_all_words() {
        let hits = fixture();
        let title = |q: &str| best(&hits, q).map(|h| h.title.as_ref());
