import json, time
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import parse_qs, urlparse

INDEXERS = [
    {"id": 1, "name": "Archive", "enable": True},
    {"id": 2, "name": "Slowpoke", "enable": True},
    {"id": 3, "name": "Broken", "enable": True},
    {"id": 4, "name": "Retired", "enable": False},
]

# .NET 서버처럼 & 와 한글을 \uXXXX 로 이스케이프한 응답 (ensure_ascii + & 치환)
ARCHIVE = [
    {"title": "ubuntu-24.04.1-desktop-amd64.iso", "size": 6203355136, "seeders": 1200,
     "indexer": "Archive", "magnetUrl": "magnet:?xt=urn:btih:0000000000000000000000000000000000000001&dn=ubuntu"},
    {"title": "우분투 한글 안내서.pdf", "size": 1048576, "seeders": 30,
     "indexer": "Archive", "magnetUrl": "magnet:?xt=urn:btih:0000000000000000000000000000000000000005"},
]
SLOW = [
    {"title": "ubuntu-24.04-live-server-amd64.iso", "size": 2754981888, "seeders": 800,
     "indexer": "Slowpoke", "downloadUrl": "http://localhost:9696/2/download?link=abc"},
]


def dotnet_json(obj):
    return json.dumps(obj, ensure_ascii=True).replace("&", "\\u0026")


class H(BaseHTTPRequestHandler):
    def log_message(self, *a):
        pass

    def send(self, code, body):
        self.send_response(code)
        self.send_header("Content-Type", "application/json")
        self.end_headers()
        self.wfile.write(body.encode())

    def do_GET(self):
        if self.headers.get("X-Api-Key") != "key":
            return self.send(401, '{"error":"Unauthorized"}')
        u = urlparse(self.path)
        if u.path == "/api/v1/indexer":
            return self.send(200, json.dumps(INDEXERS))
        if u.path == "/api/v1/search":
            ids = parse_qs(u.query).get("indexerIds", [])
            if ids == ["1"] or not ids:
                return self.send(200, dotnet_json(ARCHIVE))
            if ids == ["2"]:
                time.sleep(5)
                return self.send(200, dotnet_json(SLOW))
            if ids == ["3"]:
                return self.send(500, '{"message":"indexer exploded"}')
            return self.send(200, "[]")
        self.send(404, "")


ThreadingHTTPServer(("127.0.0.1", 19696), H).serve_forever()

