use std::fs;
use std::path::Path;
use std::sync::Arc;
use std::time::Duration;

use anyhow::{Context, Result, anyhow};
use serde::Deserialize;
use tokio::task::JoinSet;

use crate::config::Settings;

#[derive(Debug, Deserialize)]
pub struct Indexer {
    pub id: u32,
    pub name: String,
    pub enable: bool,
}

/// 인덱서 하나의 검색 결과. 실패해도 전체를 멈추지 않도록 Result를 그대로 담는다.
pub struct IndexerResult {
    pub name: String,
    pub body: Result<String>,
}

fn api_key(settings: &Settings) -> Result<&str> {
    settings
        .prowlarr_api_key
        .as_deref()
        .context("Prowlarr API 키가 필요해요 (PROWLARR_API_KEY 또는 config.toml)")
}

fn endpoint(settings: &Settings, path: &str) -> String {
    format!("{}{path}", settings.prowlarr_url.trim_end_matches('/'))
}

pub async fn indexers(http: &reqwest::Client, settings: &Settings) -> Result<Vec<Indexer>> {
    http.get(endpoint(settings, "/api/v1/indexer"))
        .header("X-Api-Key", api_key(settings)?)
        .send()
        .await
        .context("Prowlarr에 연결하지 못했어요")?
        .error_for_status()
        .context("인덱서 목록을 가져오지 못했어요 (API 키를 확인하세요)")?
        .json()
        .await
        .context("인덱서 목록을 해석하지 못했어요")
}

async fn search_one(
    http: &reqwest::Client,
    settings: &Settings,
    query: &str,
    indexer_id: u32,
) -> Result<String> {
    let id = indexer_id.to_string();
    Ok(http
        .get(endpoint(settings, "/api/v1/search"))
        .header("X-Api-Key", api_key(settings)?)
        .query(&[("query", query), ("type", "search"), ("indexerIds", &id)])
        .send()
        .await?
        .error_for_status()?
        .text()
        .await?)
}

/// 켜져 있는 인덱서마다 태스크를 하나씩 띄워 동시에 검색한다.
pub async fn search_all(
    http: &reqwest::Client,
    settings: Arc<Settings>,
    query: &str,
    timeout: Duration,
) -> Result<Vec<IndexerResult>> {
    let mut tasks = JoinSet::new();
    for ix in indexers(http, &settings).await? {
        if !ix.enable {
            continue;
        }
        // spawn한 태스크는 'static이어야 하므로, 빌린 값 대신 소유한 값을 넘긴다.
        let http = http.clone();
        let settings = Arc::clone(&settings);
        let query = query.to_owned();
        tasks.spawn(async move {
            let body = tokio::time::timeout(timeout, search_one(&http, &settings, &query, ix.id))
                .await
                .unwrap_or_else(|_| Err(anyhow!("{}초 안에 응답이 없어요", timeout.as_secs())));
            IndexerResult {
                name: ix.name,
                body,
            }
        });
    }

    let mut results = Vec::new();
    while let Some(joined) = tasks.join_next().await {
        results.push(joined.context("검색 태스크가 비정상 종료됐어요")?);
    }
    Ok(results)
}

pub fn load_fixture(path: &Path) -> Result<String> {
    fs::read_to_string(path).with_context(|| format!("{} 을 읽지 못했어요", path.display()))
}

