import json, sys
from http.server import BaseHTTPRequestHandler, HTTPServer

SESSION = "sess-42"
state = {"done": 0.0, "labels": [], "requests": 0}


class H(BaseHTTPRequestHandler):
    def log_message(self, *a):
        pass

    def send(self, code, body, headers=()):
        self.send_response(code)
        for k, v in headers:
            self.send_header(k, v)
        self.end_headers()
        self.wfile.write(body.encode())

    def do_POST(self):
        if self.path != "/transmission/rpc":
            return self.send(404, "")
        state["requests"] += 1
        if self.headers.get("X-Transmission-Session-Id") != SESSION:
            print("409 → 세션 ID 알려 줌", file=sys.stderr)
            return self.send(409, "Conflict", [("X-Transmission-Session-Id", SESSION)])
        req = json.loads(self.rfile.read(int(self.headers["Content-Length"])))
        method, args = req["method"], req.get("arguments", {})
        print(method, args, file=sys.stderr)
        if method == "torrent-add":
            state["labels"] = args.get("labels", [])
            return self.send(200, json.dumps({"result": "success", "arguments": {"torrent-added": {"id": 1}}}))
        if method == "torrent-get":
            state["done"] = min(1.0, state["done"] + 0.5)
            t = {"name": "ubuntu.iso", "percentDone": state["done"], "rateDownload": 2097152,
                 "status": 6 if state["done"] >= 1 else 4, "labels": state["labels"]}
            other = {"name": "other.iso", "percentDone": 0.1, "rateDownload": 0, "status": 0, "labels": []}
            return self.send(200, json.dumps({"result": "success", "arguments": {"torrents": [other, t]}}))
        self.send(200, json.dumps({"result": "method name not recognized"}))


HTTPServer(("127.0.0.1", 19091), H).serve_forever()

