use anyhow::{Context, Result, bail};
use serde::Deserialize;

/// qBittorrent Web API 클라이언트. 로그인 쿠키는 reqwest의 cookie_store가 들고 있는다.
pub struct Qbit {
    http: reqwest::Client,
    base: String,
}

#[derive(Debug, Deserialize)]
pub struct TorrentInfo {
    pub name: String,
    pub progress: f64,
    pub dlspeed: u64,
    pub state: String,
}

impl Qbit {
    pub async fn login(http: reqwest::Client, url: &str, user: &str, pass: &str) -> Result<Self> {
        let base = url.trim_end_matches('/').to_string();
        let body = http
            .post(format!("{base}/api/v2/auth/login"))
            .header("Referer", &base)
            .form(&[("username", user), ("password", pass)])
            .send()
            .await
            .context("qBittorrent에 연결하지 못했어요")?
            .text()
            .await?;
        if body.trim() != "Ok." {
            bail!("qBittorrent 로그인 실패 (사용자/비밀번호를 확인하세요)");
        }
        Ok(Self { http, base })
    }

    pub async fn add(&self, link: &str, save_path: Option<&str>, tag: &str) -> Result<()> {
        let mut form = vec![("urls", link), ("tags", tag)];
        if let Some(p) = save_path {
            form.push(("savepath", p));
        }
        let res = self
            .http
            .post(format!("{}/api/v2/torrents/add", self.base))
            .header("Referer", &self.base)
            .form(&form)
            .send()
            .await?;
        let status = res.status();
        let body = res.text().await.unwrap_or_default();
        if !status.is_success() || body.contains("Fails") {
            bail!("토렌트 추가 실패 ({status}): {body}");
        }
        Ok(())
    }

    pub async fn info_by_tag(&self, tag: &str) -> Result<Vec<TorrentInfo>> {
        Ok(self
            .http
            .get(format!("{}/api/v2/torrents/info", self.base))
            .header("Referer", &self.base)
            .query(&[("tag", tag)])
            .send()
            .await?
            .error_for_status()?
            .json()
            .await?)
    }
}

