use std::io::{self, Write};

use anyhow::Result;

use crate::hit::Hit;
use crate::qbit::TorrentInfo;

/// 목록을 찍는다. recommended와 **같은 항목(같은 메모리 위치)** 앞에 ★를 붙인다.
pub fn print_hits(hits: &[Hit], recommended: Option<&Hit>) {
    for (i, h) in hits.iter().enumerate() {
        let mark = if recommended.is_some_and(|r| std::ptr::eq(r, h)) {
            "★"
        } else {
            " "
        };
        println!(
            "{mark}{:>2}) {}\n      {}  seeders {}  [{}]",
            i + 1,
            h.title,
            human_size(h.size),
            h.seeders(),
            h.indexer
        );
    }
}

pub fn prompt_choice(max: usize) -> Result<Option<usize>> {
    loop {
        print!("선택 (1-{max}, 엔터=취소)> ");
        io::stdout().flush()?;

        let mut line = String::new();
        io::stdin().read_line(&mut line)?;
        let line = line.trim();

        if line.is_empty() || line.eq_ignore_ascii_case("q") {
            return Ok(None);
        }
        match line.parse::<usize>() {
            Ok(n) if (1..=max).contains(&n) => return Ok(Some(n - 1)),
            _ => println!("1-{max} 사이 숫자를 입력하세요"),
        }
    }
}

/// 한 줄을 \r 로 덮어쓰며 진행률을 그린다.
pub fn print_progress(t: &TorrentInfo) -> Result<()> {
    const WIDTH: usize = 20;
    let filled = ((t.progress * WIDTH as f64) as usize).min(WIDTH);
    print!(
        "\r[{}{}] {:>5.1}%  {}/s  {}    ",
        "#".repeat(filled),
        "-".repeat(WIDTH - filled),
        t.progress * 100.0,
        human_size(t.dlspeed),
        t.state
    );
    io::stdout().flush()?;
    Ok(())
}

pub fn human_size(bytes: u64) -> String {
    const UNITS: [&str; 5] = ["B", "KB", "MB", "GB", "TB"];
    let mut v = bytes as f64;
    let mut u = 0;
    while v >= 1024.0 && u < UNITS.len() - 1 {
        v /= 1024.0;
        u += 1;
    }
    format!("{v:.1}{}", UNITS[u])
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn human_size_units() {
        assert_eq!(human_size(0), "0.0B");
        assert_eq!(human_size(1023), "1023.0B");
        assert_eq!(human_size(1024), "1.0KB");
        assert_eq!(human_size(1536), "1.5KB");
        assert_eq!(human_size(5 * 1024 * 1024 * 1024), "5.0GB");
    }

    #[test]
    fn human_size_caps_at_tb() {
        assert_eq!(human_size(2048 * 1024u64.pow(4)), "2048.0TB");
    }
}

