use std::sync::Arc;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

use anyhow::{Context, Result, bail};
use clap::Parser;

use cli::Args;
use config::Settings;
use qbit::Qbit;

#[tokio::main]
async fn main() -> Result<()> {
    let args = Args::parse();
    let settings = Arc::new(Settings::load(&args)?);
    let http = reqwest::Client::builder().cookie_store(true).build()?;

    let raws = match &args.fixture {
        Some(path) => vec![prowlarr::load_fixture(path)?],
        None => {
            let timeout = Duration::from_secs(args.timeout);
            let results =
                prowlarr::search_all(&http, Arc::clone(&settings), &args.query, timeout).await?;
            let mut raws = Vec::new();
            for r in results {
                match r.body {
                    Ok(body) => raws.push(body),
                    Err(e) => eprintln!("⚠ {}: {e:#}", r.name),
                }
            }
            raws
        }
    };

    let mut hits = Vec::new();
    for raw in &raws {
        hits.extend(hit::parse(raw).context("검색 결과를 해석하지 못했어요")?);
    }
    let hits = hit::rank(hits, args.min_seeders, args.limit);

    if hits.is_empty() {
        bail!("'{}' 에 해당하는 토렌트를 찾지 못했어요", args.query);
    }

    let recommended = hit::best(&hits, &args.query);
    ui::print_hits(&hits, recommended);

    if args.dry_run {
        return Ok(());
    }

    let chosen = if args.first {
        recommended.unwrap_or(&hits[0])
    } else {
        match ui::prompt_choice(hits.len())? {
            Some(i) => &hits[i],
            None => {
                println!("취소했어요");
                return Ok(());
            }
        }
    };

    let qbit = Qbit::login(
        http,
        &settings.qbit_url,
        &settings.qbit_user,
        &settings.qbit_pass,
    )
    .await?;
    let tag = new_tag();
    qbit.add(chosen.link().unwrap(), settings.save_path.as_deref(), &tag)
        .await?;
    println!("→ qBittorrent에 추가됨: {}", chosen.title);

    if args.watch {
        watch(&qbit, &tag).await?;
    }
    Ok(())
}

/// 이번에 추가한 토렌트만 찾아내기 위한 고유 태그.
fn new_tag() -> String {
    let secs = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0);
    format!("tget-{secs}")
}

async fn watch(qbit: &Qbit, tag: &str) -> Result<()> {
    println!("진행률을 지켜보는 중… (Ctrl+C로 그만 보기, 다운로드는 계속돼요)");
    loop {
        // magnet은 메타데이터를 받기 전까지 목록에 늦게 나타날 수 있다.
        if let Some(t) = qbit.info_by_tag(tag).await?.first() {
            ui::print_progress(t)?;
            if t.progress >= 1.0 {
                println!("\n완료: {}", t.name);
                return Ok(());
            }
        }
        tokio::time::sleep(Duration::from_secs(2)).await;
    }
}

