use std::path::PathBuf;

use thiserror::Error;

/// tget이 "알고 있는" 실패들. 종류마다 다른 종료 코드를 준다.
#[derive(Debug, Error)]
pub enum TgetError {
    #[error("설정 파일 {} 을 읽지 못했어요", path.display())]
    ConfigRead {
        path: PathBuf,
        #[source]
        source: std::io::Error,
    },

    #[error("설정 파일 {} 형식이 잘못됐어요", path.display())]
    ConfigParse {
        path: PathBuf,
        #[source]
        source: toml::de::Error,
    },

    #[error("Prowlarr API 키가 필요해요 (PROWLARR_API_KEY 또는 config.toml)")]
    MissingApiKey,

    #[error("{service} 인증 실패 (API 키나 비밀번호를 확인하세요)")]
    Unauthorized { service: &'static str },

    #[error("{service}에 연결하지 못했어요")]
    Connect {
        service: &'static str,
        #[source]
        source: reqwest::Error,
    },

    #[error("{secs}초 안에 응답이 없어요")]
    Timeout { secs: u64 },

    #[error("검색 태스크가 비정상 종료됐어요")]
    Task(#[from] tokio::task::JoinError),

    #[error(transparent)]
    Http(#[from] reqwest::Error),
}

impl TgetError {
    /// 셸 스크립트에서 실패 원인을 구분할 수 있게 하는 종료 코드.
    pub fn exit_code(&self) -> u8 {
        match self {
            TgetError::ConfigRead { .. } | TgetError::ConfigParse { .. } => 2,
            TgetError::MissingApiKey | TgetError::Unauthorized { .. } => 3,
            TgetError::Connect { .. } | TgetError::Timeout { .. } | TgetError::Http(_) => 4,
            TgetError::Task(_) => 1,
        }
    }
}

/// 원인 사슬 어딘가에 TgetError가 있으면 그 종료 코드, 없으면 1.
/// context가 몇 겹 씌워져 있어도 찾아낸다.
pub fn exit_code_of(err: &anyhow::Error) -> u8 {
    err.chain()
        .find_map(|cause| cause.downcast_ref::<TgetError>())
        .map_or(1, TgetError::exit_code)
}

#[cfg(test)]
mod tests {
    use super::*;
    use anyhow::Context;

    #[test]
    fn exit_code_survives_context() {
        let err: anyhow::Result<()> = Err(TgetError::MissingApiKey.into());
        let err = err.context("검색 준비 중").unwrap_err();
        assert_eq!(exit_code_of(&err), 3);
    }

    #[test]
    fn unknown_errors_exit_with_1() {
        assert_eq!(exit_code_of(&anyhow::anyhow!("뭔가 잘못됨")), 1);
    }
}

