use std::fs;
use std::path::{Path, PathBuf};

use serde::Deserialize;

use crate::cli::Args;
use crate::downloader::ClientKind;
use crate::error::TgetError;

/// config.toml 의 모양. 모든 칸이 비어 있어도 된다.
#[derive(Debug, Default, Deserialize)]
pub struct FileConfig {
    pub prowlarr_url: Option<String>,
    pub prowlarr_api_key: Option<String>,
    pub qbit_url: Option<String>,
    pub qbit_user: Option<String>,
    pub qbit_pass: Option<String>,
    pub save_path: Option<String>,
    pub client: Option<ClientKind>,
    pub transmission_url: Option<String>,
    pub transmission_user: Option<String>,
    pub transmission_pass: Option<String>,
}

/// CLI/환경변수 > 설정 파일 > 기본값 순으로 합친 최종 설정.
#[derive(Debug)]
pub struct Settings {
    pub prowlarr_url: String,
    pub prowlarr_api_key: Option<String>,
    pub qbit_url: String,
    pub qbit_user: String,
    pub qbit_pass: String,
    pub save_path: Option<String>,
    pub client: ClientKind,
    pub transmission_url: String,
    pub transmission_user: Option<String>,
    pub transmission_pass: Option<String>,
}

impl Settings {
    pub fn load(args: &Args) -> Result<Self, TgetError> {
        let file = match &args.config {
            Some(path) => read_file(path)?,
            None => match default_path() {
                Some(path) if path.exists() => read_file(&path)?,
                _ => FileConfig::default(),
            },
        };
        Ok(Self::merge(args, file))
    }

    fn merge(args: &Args, file: FileConfig) -> Self {
        Self {
            prowlarr_url: args
                .prowlarr_url
                .clone()
                .or(file.prowlarr_url)
                .unwrap_or_else(|| "http://localhost:9696".into()),
            prowlarr_api_key: args.prowlarr_api_key.clone().or(file.prowlarr_api_key),
            qbit_url: args
                .qbit_url
                .clone()
                .or(file.qbit_url)
                .unwrap_or_else(|| "http://localhost:8080".into()),
            qbit_user: args
                .qbit_user
                .clone()
                .or(file.qbit_user)
                .unwrap_or_else(|| "admin".into()),
            qbit_pass: args
                .qbit_pass
                .clone()
                .or(file.qbit_pass)
                .unwrap_or_default(),
            save_path: args.save_path.clone().or(file.save_path),
            client: args.client.or(file.client).unwrap_or_default(),
            transmission_url: args
                .transmission_url
                .clone()
                .or(file.transmission_url)
                .unwrap_or_else(|| "http://localhost:9091/transmission/rpc".into()),
            transmission_user: args.transmission_user.clone().or(file.transmission_user),
            transmission_pass: args.transmission_pass.clone().or(file.transmission_pass),
        }
    }
}

fn default_path() -> Option<PathBuf> {
    let base = std::env::var_os("XDG_CONFIG_HOME")
        .map(PathBuf::from)
        .or_else(|| dirs::home_dir().map(|h| h.join(".config")))?;
    Some(base.join("tget").join("config.toml"))
}

fn read_file(path: &Path) -> Result<FileConfig, TgetError> {
    let raw = fs::read_to_string(path).map_err(|source| TgetError::ConfigRead {
        path: path.to_path_buf(),
        source,
    })?;
    toml::from_str(&raw).map_err(|source| TgetError::ConfigParse {
        path: path.to_path_buf(),
        source,
    })
}

