use std::sync::Mutex;

use anyhow::{Context, Result, bail};
use reqwest::StatusCode;
use serde::Deserialize;
use serde_json::{Value, json};

use crate::downloader::{Downloader, Progress};
use crate::error::TgetError;

const SESSION_HEADER: &str = "X-Transmission-Session-Id";

/// Transmission RPC 클라이언트.
/// 세션 ID는 서버가 409로 알려 줄 때마다 바뀌므로, &self 메서드 안에서도 고칠 수 있게 Mutex에 둔다.
pub struct Transmission {
    http: reqwest::Client,
    url: String,
    user: Option<String>,
    pass: Option<String>,
    session_id: Mutex<String>,
}

#[derive(Deserialize)]
struct RpcResponse {
    result: String,
    #[serde(default)]
    arguments: Value,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Torrent {
    name: String,
    percent_done: f64,
    rate_download: u64,
    status: i64,
    #[serde(default)]
    labels: Vec<String>,
}

impl Transmission {
    pub fn new(
        http: reqwest::Client,
        url: &str,
        user: Option<String>,
        pass: Option<String>,
    ) -> Self {
        Self {
            http,
            url: url.to_string(),
            user,
            pass,
            session_id: Mutex::new(String::new()),
        }
    }

    async fn rpc(&self, method: &str, arguments: Value) -> Result<Value> {
        let body = json!({ "method": method, "arguments": arguments });
        // 첫 요청은 세션 ID가 없어서 409를 받는 게 정상이다. 한 번 갱신하고 다시 보낸다.
        for _ in 0..2 {
            // lock()이 돌려준 가드는 이 문장이 끝나면 바로 풀린다. await 너머로 들고 가지 않는다.
            let session_id = self.session_id.lock().unwrap().clone();
            let mut req = self
                .http
                .post(&self.url)
                .header(SESSION_HEADER, session_id)
                .json(&body);
            if let Some(user) = &self.user {
                req = req.basic_auth(user, self.pass.as_deref());
            }
            let res = req.send().await.map_err(|source| TgetError::Connect {
                service: "Transmission",
                source,
            })?;

            if res.status() == StatusCode::UNAUTHORIZED {
                return Err(TgetError::Unauthorized {
                    service: "Transmission",
                }
                .into());
            }

            if res.status() == StatusCode::CONFLICT {
                let new_id = res
                    .headers()
                    .get(SESSION_HEADER)
                    .and_then(|v| v.to_str().ok())
                    .context("Transmission이 세션 ID를 주지 않았어요")?;
                *self.session_id.lock().unwrap() = new_id.to_string();
                continue;
            }

            let res: RpcResponse = res
                .error_for_status()
                .context("Transmission 요청 실패 (사용자/비밀번호를 확인하세요)")?
                .json()
                .await
                .context("Transmission 응답을 해석하지 못했어요")?;
            if res.result != "success" {
                bail!("Transmission 오류: {}", res.result);
            }
            return Ok(res.arguments);
        }
        bail!("Transmission 세션을 맺지 못했어요")
    }
}

fn status_name(status: i64) -> &'static str {
    match status {
        0 => "stopped",
        1 | 2 => "checking",
        3 => "queued",
        4 => "downloading",
        5 | 6 => "seeding",
        _ => "unknown",
    }
}

impl Downloader for Transmission {
    fn name(&self) -> &'static str {
        "Transmission"
    }

    async fn add(&self, link: &str, save_path: Option<&str>, tag: &str) -> Result<()> {
        let mut args = json!({ "filename": link, "labels": [tag] });
        if let Some(p) = save_path {
            args["download-dir"] = json!(p);
        }
        self.rpc("torrent-add", args).await?;
        Ok(())
    }

    async fn progress(&self, tag: &str) -> Result<Option<Progress>> {
        let fields = ["name", "percentDone", "rateDownload", "status", "labels"];
        let args = self.rpc("torrent-get", json!({ "fields": fields })).await?;
        let torrents: Vec<Torrent> = serde_json::from_value(args["torrents"].clone())
            .context("Transmission 토렌트 목록을 해석하지 못했어요")?;
        Ok(torrents
            .into_iter()
            .find(|t| t.labels.iter().any(|l| l == tag))
            .map(|t| Progress {
                name: t.name,
                done: t.percent_done,
                speed: t.rate_download,
                state: status_name(t.status).to_string(),
            }))
    }
}

